"""Rich Ukrainian fallback copy for Together reports when AI is unavailable."""

from .together_depth import deepen_together_text

ASPECT_UA = {
    "conjunction": "сполучення", "opposition": "опозиція", "trine": "тригон",
    "square": "квадрат", "sextile": "секстиль",
}
PLANET_UA = {
    "sun": "Сонце", "moon": "Місяць", "mercury": "Меркурій",
    "venus": "Венера", "mars": "Марс", "jupiter": "Юпітер",
    "saturn": "Сатурн", "uranus": "Уран", "neptune": "Нептун",
    "pluto": "Плутон", "ascendant": "Асцендент",
}


def _evidence_sentence(context: dict) -> str:
    aspects = context.get("strongest_aspects") or []
    if not aspects:
        return "У розрахунку немає одного домінантного аспекту, тому важливіше дивитися на повторювані сценарії взаємодії."
    aspect = aspects[0]
    left = PLANET_UA.get(aspect.get("planet_a", ""), aspect.get("planet_a", "планета першої людини"))
    right = PLANET_UA.get(aspect.get("planet_b", ""), aspect.get("planet_b", "планета другої людини"))
    relation = ASPECT_UA.get(aspect.get("aspect", ""), aspect.get("aspect", "аспект"))
    orb = aspect.get("orb")
    detail = f" з орбісом {orb:.1f}°" if isinstance(orb, (int, float)) else ""
    return f"Один із найвиразніших показників карти — {left} першої людини та {right} другої утворюють {relation}{detail}."


def build_together_fallback(context: dict, profile_a: dict, profile_b: dict) -> str:
    a = context.get("person_a", {}).get("name") or profile_a.get("name", "Перша людина")
    b = context.get("person_b", {}).get("name") or profile_b.get("name", "Друга людина")
    evidence = _evidence_sentence(context)
    sections = [
        ("Секція 01. Що вас притягує", f"Між {a} та {b} притягання виникає не лише через подібність, а й через різницю способів реагувати. Один може швидше задавати напрям і переводити бажання в дію, тоді як інший тонше відчуває атмосферу та помічає те, що залишилося невисловленим. Саме ця відмінність підтримує інтерес: поруч є людина, яка бачить ситуацію з іншого боку.\n\n{evidence} Це не гарантія постійної легкості, але конкретна точка взаємного включення. Щоб потяг не перетворювався на боротьбу за увагу, важливо прямо називати, що саме захоплює у партнері, і не вимагати однакового темпу зближення."),
        ("Секція 02. Емоційна близькість", "Емоційна близькість у цій парі будується через передбачуваність і безпечну реакцію на вразливість. Коли один ділиться переживанням, другому корисно спочатку підтвердити почуте, а вже потім пропонувати рішення. Інакше турбота може помилково сприйматися як холодність, контроль або небажання слухати.\n\nВам важливо розрізняти мовчання і відсторонення. Мовчання іноді означає, що людині потрібен час упорядкувати емоції. Домовтеся про простий сигнал: «я не зникаю, мені потрібно трохи часу, повернімося до розмови ввечері». Це зменшує тривогу й не дає уяві заповнювати паузу негативними припущеннями."),
        ("Секція 03. Як ви проявляєте любов", "Любов може проявлятися різними каналами: словами, конкретною допомогою, фізичною близькістю, спільним часом або турботою про побут. Проблема виникає не через брак почуттів, а коли кожен віддає любов у власній формі й очікує отримати її так само. Тоді реальні зусилля партнера залишаються непоміченими.\n\nСкладіть для себе короткий список із трьох дій, після яких ви особливо відчуваєте турботу. Обміняйтеся списками без критики та торгу. Для цієї пари конкретні прохання працюватимуть краще за перевірки на кшталт «якби любив, сам би здогадався»."),
        ("Секція 04. Як ви говорите і чуєте одне одного", "У розмовах один із вас може швидше переходити до висновку, а другому потрібні деталі, контекст і час сформулювати позицію. Через це коротка відповідь іноді звучить як різкість, а довге пояснення — як ухиляння від суті. Обидва стилі мають сенс, але потребують перекладу.\n\nПід час важливої розмови використовуйте три кроки: факт без оцінки, власне відчуття, конкретне прохання. Наприклад: «ми двічі перенесли зустріч; я засмутився; скажи, який день справді реалістичний». Такий формат не гарантує згоди, зате зменшує захист і допомагає почути реальну потребу."),
        ("Секція 05. Напруга і конфлікти", "Головний ризик конфлікту — сперечатися вже не про подію, а про характер партнера. Слова «ти завжди» або «ти ніколи» швидко переводять розмову в захист. Напруга може посилюватися, коли один тисне заради ясності, а інший віддаляється, щоб повернути контроль над собою. Чим сильніше переслідування, тим сильніша дистанція.\n\nЗупиняйте конфлікт до моменту, коли метою стає перемога. Пауза має містити час повернення до теми, інакше вона сприйматиметься як покарання. Після розмови сформулюйте одну практичну домовленість, яку можна перевірити, замість обіцянки «більше так не робити»."),
        ("Секція 06. Що тримає вас разом", "Стабільність цієї пари створюють не гучні декларації, а повторювані маленькі дії: виконана обіцянка, увага до стану партнера, готовність повернутися до незручної розмови. Відчуття «ми — команда» зміцнюється, коли зовнішня проблема не перетворюється на взаємне звинувачення.\n\nКорисно мати спільний ритуал, який не залежить від настрою: прогулянку, вечерю без телефонів або щотижневу розмову про плани. Ритуал не має бути романтичним за формою — його завдання регулярно нагадувати, що стосунки отримують окреме місце серед роботи, побуту та інших людей."),
        ("Секція 07. Чого один може не розуміти про іншого", "Один із вас може вважати прямоту проявом чесності, тоді як інший чує в ній знецінення. І навпаки: обережність та натяки можуть бути спробою зберегти контакт, але партнер сприйматиме їх як неясність. Тут легко приписати іншому намір, якого насправді не було.\n\nПеред реакцією перевіряйте інтерпретацію запитанням: «Я почув це так… ти це мав на увазі?» Особливо важливо не пояснювати партнеру його власні почуття. Цікавість дасть більше інформації, ніж діагноз. Різниця не обов’язково потребує виправлення — іноді достатньо знати, як вона працює."),
        ("Секція 08. Ваша сила як пари", "Сила пари проявляється там, де різні якості складаються в один результат. Один може краще бачити можливість і запускати рух, інший — оцінювати наслідки, підтримувати ритм або помічати людський бік рішення. Разом ви здатні приймати об’ємніші рішення, ніж кожен окремо, якщо не плутаєте відмінну думку з нелояльністю.\n\nВикористовуйте це свідомо: перед важливим кроком нехай кожен окремо назве можливість, ризик і необхідний ресурс. Так ви не змагатиметеся за роль «того, хто має рацію», а об’єднаєте дві перспективи в спільну стратегію."),
        ("Секція 09. Де потрібна увага", "Найбільше уваги потребують невисловлені очікування. Якщо домовленість існує лише в голові одного, другий не може свідомо її виконати. Накопичення дрібних розчарувань небезпечніше за одну відкриту суперечку: з часом воно створює дистанцію й змушує бачити кожну нову подію крізь стару образу.\n\nРаз на місяць обговорюйте три питання: що між нами зараз працює, чого стало замало, яку одну зміну ми спробуємо наступного місяця. Не намагайтеся виправити все одразу. Одна конкретна й взаємна дія дає стосункам більше, ніж великий список претензій без пріоритету."),
    ]
    ending = """П'ять речей, які важливо знати:
1. Різний темп реакції не означає байдужості.
2. Пряме прохання надійніше за перевірку, чи партнер здогадається.
3. Пауза в конфлікті корисна, якщо визначено час повернення.
4. Власний простір не суперечить близькості.
5. Стабільність створюють повторювані дії, а не разові обіцянки.

Що спробувати:
- Раз на тиждень проводити щонайменше годину без телефонів.
- Перед порадою запитувати: «Тобі зараз потрібна підтримка чи рішення?»
- Раз на місяць переглядати одну спільну домовленість."""
    base_text = "\n\n".join(f"{title}\n\n{body}" for title, body in sections)
    return deepen_together_text(base_text, context)
